const WINDOW = 15
const COOPERATION_THRESHOLD = 0.7
const EXPLOIT_THRESHOLD = 0.4
const MIN_DEFECT_RESPONSE_SAMPLES = 3
const OLIVE_BRANCH_SCHEDULE = [5, 20, 70]

function freshMemory() {
	return {
		seen: 0,
		opponentC: 0,
		opponentD: 0,
		mutualDStreak: 0,
		olives: 0,
	}
}

function rebuildMemory(history, previous) {
	const memory = freshMemory()
	memory.olives =
		previous && Number.isFinite(previous.olives)
			? Math.max(0, Math.floor(previous.olives))
			: 0

	for (let i = 0; i < history.length; i++) {
		const round = history[i]
		if (round.opponent === "D") memory.opponentD++
		else memory.opponentC++

		if (round.you === "D" && round.opponent === "D")
			memory.mutualDStreak++
		else memory.mutualDStreak = 0
	}

	memory.seen = history.length
	return memory
}

function updateMemory(history, memory) {
	const n = history.length

	// Under normal tournament execution, memory.seen is n - 1. Rebuild if
	// memory was malformed or became inconsistent instead of risking a crash.
	if (
		!memory ||
		typeof memory !== "object" ||
		memory.seen !== n - 1 ||
		!Number.isFinite(memory.opponentC) ||
		!Number.isFinite(memory.opponentD) ||
		!Number.isFinite(memory.mutualDStreak) ||
		!Number.isFinite(memory.olives)
	)
		return rebuildMemory(history, memory)

	const last = history[n - 1]
	if (last.opponent === "D") memory.opponentD++
	else memory.opponentC++

	if (last.you === "D" && last.opponent === "D")
		memory.mutualDStreak++
	else memory.mutualDStreak = 0

	memory.seen = n
	return memory
}

function smoothedRate(successes, samples) {
	// Jeffreys-style smoothing prevents tiny samples from producing certainty.
	return (successes + 0.5) / (samples + 1)
}

function responseRates(history) {
	let cooperateAfterC = 0
	let samplesAfterC = 0
	let cooperateAfterD = 0
	let samplesAfterD = 0
	const start = Math.max(1, history.length - WINDOW)

	// Their move at i can be a response to our move at i - 1.
	for (let i = start; i < history.length; i++) {
		const ourPreviousMove = history[i - 1].you
		const theirMove = history[i].opponent

		if (ourPreviousMove === "C") {
			samplesAfterC++
			if (theirMove === "C") cooperateAfterC++
		} else {
			samplesAfterD++
			if (theirMove === "C") cooperateAfterD++
		}
	}

	return {
		pC: smoothedRate(cooperateAfterC, samplesAfterC),
		pD: smoothedRate(cooperateAfterD, samplesAfterD),
		samplesAfterD,
	}
}

function isUnconditionalPeriodic(history) {
	const n = history.length
	const PERIOD_WINDOW = 20
	if (n < 12) return false

	const start = Math.max(0, n - PERIOD_WINDOW)
	let sawC = false
	let sawD = false

	for (let i = start; i < n; i++) {
		if (history[i].opponent === "C") sawC = true
		else sawD = true
	}
	if (!sawC || !sawD) return false

	for (let period = 2; period <= 6; period++) {
		let matches = true
		let comparisons = 0

		for (let i = start + period; i < n; i++) {
			comparisons++
			if (history[i].opponent !== history[i - period].opponent) {
				matches = false
				break
			}
		}

		if (!matches || comparisons < 8) continue

		// Do not call ordinary lag-one tit-for-tat an unconditional pattern.
		let explainedByTitForTat = true
		for (let i = Math.max(1, start); i < n; i++) {
			if (history[i].opponent !== history[i - 1].you) {
				explainedByTitForTat = false
				break
			}
		}

		if (!explainedByTitForTat) return true
	}

	return false
}

function decide(history, memory) {
	const n = history.length
	if (n === 0) return ["C", freshMemory()]

	memory = updateMemory(history, memory)
	const last = history[n - 1]
	const previous = n >= 2 ? history[n - 2] : null

	// Never disturb pristine cooperation. Probing cannot distinguish an
	// always-cooperator from a grudger without risking the whole relationship.
	if (memory.opponentD === 0) return ["C", memory]

	// Fixed alternators and other short unconditional cycles are best met by D.
	if (isUnconditionalPeriodic(history)) return ["D", memory]

	const { pC, pD, samplesAfterD } = responseRates(history)

	// If they have repeatedly cooperated after our D, continued defection has
	// demonstrated positive value. Re-evaluate every turn so retaliation exits
	// this behavior instead of locking us into it forever.
	if (
		samplesAfterD >= MIN_DEFECT_RESPONSE_SAMPLES &&
		pD >= EXPLOIT_THRESHOLD
	)
		return ["D", memory]

	// A responsive opponent is valuable. Punish only an unprovoked D. If their
	// D followed our D, cooperate to break a retaliation loop (contrition).
	if (pC >= COOPERATION_THRESHOLD) {
		const theirDWasProvoked =
			last.opponent === "D" &&
			previous !== null &&
			previous.you === "D"

		if (last.opponent === "D" && !theirDWasProvoked)
			return ["D", memory]

		return ["C", memory]
	}

	// In an unproductive DD loop, occasionally test for recovery only if this
	// opponent has cooperated before. Never donate points to a pure defector.
	if (
		memory.opponentC > 0 &&
		memory.olives < OLIVE_BRANCH_SCHEDULE.length &&
		memory.mutualDStreak >= OLIVE_BRANCH_SCHEDULE[memory.olives]
	) {
		memory.olives++
		return ["C", memory]
	}

	return ["D", memory]
}

export default function bot(state) {
	let memory =
		state && state.memory && typeof state.memory === "object"
			? state.memory
			: null

	try {
		const history =
			state && Array.isArray(state.history) ? state.history : []
		const [move, nextMemory] = decide(history, memory)
		return [move === "C" ? "C" : "D", nextMemory]
	} catch {
		// A conservative valid move is much better than forfeiting the battle.
		return ["D", memory ?? freshMemory()]
	}
}

export default function bot({ history, memory }) {
  try {
    const C = "C", D = "D"
    if (memory == null || typeof memory !== "object" || !Array.isArray(memory.win)) {
      memory = { doom: false, nat: 0, dStrk: 0, cStrk: 0, oppC: 0, oppD: 0, win: [], dWin: [], late: [] }
    }
    if (!Array.isArray(memory.dWin)) memory.dWin = []
    if (!Array.isArray(memory.late)) memory.late = []

    const n = history.length
    if (n === 0) return [C, memory]

    const last = history[n - 1]
    const opp = last.opponent === D ? D : C
    const me = last.you === D ? D : C
    const prevMe = n >= 2 ? (history[n - 2].you === D ? D : C) : C

    memory.dStrk = opp === D ? memory.dStrk + 1 : 0
    memory.cStrk = opp === C ? memory.cStrk + 1 : 0
    if (opp === D) memory.oppD++; else memory.oppC++

    const unprovoked = opp === D && me === C && prevMe === C
    if (unprovoked) memory.nat++

    if (n >= 2) {
      memory.win.push(opp === prevMe ? 1 : 0)
      if (memory.win.length > 40) memory.win.shift()
    }
    if (n >= 2 && prevMe === C) {
      memory.dWin.push(opp === D ? 1 : 0)
      if (memory.dWin.length > 14) memory.dWin.shift()
    }

    const tot = memory.oppC + memory.oppD
    const oppDR = tot ? memory.oppD / tot : 0
    let reactivity = 0.5
    if (memory.win.length >= 10) {
      reactivity = memory.win.reduce((a, b) => a + b, 0) / memory.win.length
    }
    const looksRandom = memory.win.length >= 15 && reactivity < 0.62 && oppDR > 0.28

    if (memory.doom) {
      if (looksRandom) return [D, memory]
      if (memory.cStrk >= 3) { memory.doom = false; memory.nat = 0 }
      else return [D, memory]
    }
    if (memory.dStrk >= 2 && memory.nat >= 1) {
      memory.doom = true
      return [D, memory]
    }
    if (
      n >= 20 &&
      memory.dWin.length >= 14 &&
      memory.dWin.reduce((a, b) => a + b, 0) >= 5
    ) {
      memory.doom = true
      return [D, memory]
    }

    if (n >= 90) {
      memory.late.push(opp === D ? 1 : 0)
      if (memory.late.length > 12) memory.late.shift()
      if (memory.late.length >= 8 && memory.late.reduce((a, b) => a + b, 0) >= 3) {
        return [D, memory]
      }
    }

    if (opp === C) return [C, memory]
    if (me === D) return [C, memory]
    if (unprovoked) return [D, memory]
    return [C, memory]
  } catch (e) {
    try {
      if (history && history.length > 0) {
        return [history[history.length - 1].opponent === "D" ? "D" : "C", memory ?? null]
      }
    } catch (e2) {}
    return ["C", null]
  }
}

const T = 3 // temptation  (I defect, they cooperate)
const R = 2 // reward      (both cooperate)
const P = 1 // punishment  (both defect)
const S = 0 // sucker      (I cooperate, they defect)

const WINDOW = 40 // rounds of recent behaviour we judge them on
const RESPONSIVE_MARGIN = 0.1 // extra confidence before trusting them
const OLIVE_SCHEDULE = [3, 10, 25, 60, 130, 280, 600] // mutual-D streaks at which we try C
const TEST_SCHEDULE = [3, 12, 40, 120, 300] // coop streaks at which we test if they punish
const MAX_FAILED_TESTS = 2 // stop testing once they've retaliated twice
const MAX_OLIVES_VS_PURE_DEFECTOR = 2 // if they've never cooperated, don't keep paying
const PROBE_ROUND = 0 // >0 = defect once at that round to sniff always-C bots (risky vs grudgers; off by default)

function smooth(c, n) {
  return (c + 0.5) / (n + 1)
}

function isUnconditionalPeriodic(history) {
  const L = 20
  const t = history.length
  if (t < 12) return false
  const from = Math.max(0, t - L)
  let sawC = false, sawD = false
  for (let i = from; i < t; i++) {
    if (history[i].opponent === "C") sawC = true
    else sawD = true
  }
  if (!(sawC && sawD)) return false // pure C / pure D handled elsewhere

  let periodic = false
  for (let p = 2; p <= 6 && !periodic; p++) {
    let ok = true, checks = 0
    for (let i = from + p; i < t; i++) {
      checks++
      if (history[i].opponent !== history[i - p].opponent) { ok = false; break }
    }
    if (ok && checks >= 8) periodic = true
  }
  if (!periodic) return false

  // Could this same sequence be tit-for-tat reacting to us? Then it's ambiguous -> not unconditional.
  for (let i = Math.max(1, from); i < t; i++) {
    if (history[i].opponent !== history[i - 1].you) return true
  }
  return false
}

function decide(history, memory) {
  const t = history.length
  if (t === 0) return ["C", memory]

  // ---------- one pass over history for the facts we need ----------
  let oppEverD = false
  let oppEverC = false
  for (let i = 0; i < t; i++) {
    if (history[i].opponent === "D") oppEverD = true
    else oppEverC = true
  }

  const last = history[t - 1]
  const prev = t >= 2 ? history[t - 2] : null

  // Opponent's move at round i is a response to OUR move at round i-1.
  // Windowed conditional cooperation rates.
  let cC = 0, nC = 0, cD = 0, nD = 0
  const start = Math.max(1, t - WINDOW)
  for (let i = start; i < t; i++) {
    const ours = history[i - 1].you
    const theirs = history[i].opponent
    if (ours === "C") { nC++; if (theirs === "C") cC++ }
    else { nD++; if (theirs === "C") cD++ }
  }
  const pC = smooth(cC, nC)
  const pD = smooth(cD, nD)

  // streaks
  let mutualDStreak = 0
  for (let i = t - 1; i >= 0 && history[i].you === "D" && history[i].opponent === "D"; i--) mutualDStreak++
  let coopStreak = 0
  for (let i = t - 1; i >= 0 && history[i].you === "C" && history[i].opponent === "C"; i--) coopStreak++

  // ---------- optional unprovoked probe ----------
  if (!oppEverD && !memory.probed && PROBE_ROUND > 0 && t === PROBE_ROUND) {
    memory.probed = true
    return ["D", memory]
  }

  const provoked = oppEverD || memory.probed === true

  // ---------- peace: they've never defected -> keep cooperating ----------
  if (!provoked) return ["C", memory]

  // ---------- 0. periodic / unconditional pattern? ----------
  // Bots like alternators (D,C,D,C…) or "C,C,D" repeaters ignore us.
  // If their recent moves follow a fixed period AND are not explained
  // by copying our moves, the best response is always D.
  if (isUnconditionalPeriodic(history)) return ["D", memory]

  // ---------- evaluate exploration bookkeeping ----------
  // A "test" = we defected during cooperation to see if they punish.
  let failedTests = 0
  for (const r of memory.tests) {
    if (r + 1 < t && history[r + 1].opponent === "D") failedTests++
  }

  // ---------- 1. exploitable? defecting beats mutual cooperation ----------
  // value of defecting forever = T*pD + P*(1-pD) ; compare with R
  const exploitThreshold = (R - P) / (T - P)
  if (nD >= 2 && pD >= exploitThreshold) {
    return ["D", memory]
  }

  // ---------- 2. responsive? cooperating beats mutual defection ----------
  const responsiveThreshold = (P - S) / (R - S) + RESPONSIVE_MARGIN
  const lastOppD = last.opponent === "D"
  const theirDWasProvoked = prev !== null && prev.you === "D"

  if (pC >= responsiveThreshold) {
    // retaliate only for UNPROVOKED defection (contrite tit-for-tat)
    if (lastOppD && !theirDWasProvoked) return ["D", memory]

    // test whether they actually punish us (bounded, backed-off)
    if (
      !lastOppD &&
      failedTests < MAX_FAILED_TESTS &&
      memory.tests.length < TEST_SCHEDULE.length &&
      coopStreak >= TEST_SCHEDULE[memory.tests.length]
    ) {
      memory.tests.push(t)
      return ["D", memory]
    }
    return ["C", memory]
  }

  // ---------- 3. unresponsive: defect, with occasional olive branch ----------
  const oliveCap = oppEverC ? OLIVE_SCHEDULE.length : MAX_OLIVES_VS_PURE_DEFECTOR
  if (
    memory.olives < oliveCap &&
    memory.olives < OLIVE_SCHEDULE.length &&
    mutualDStreak >= OLIVE_SCHEDULE[memory.olives]
  ) {
    memory.olives++
    return ["C", memory]
  }
  return ["D", memory]
}

export default function bot(state) {
  let memory = null
  try {
    const history = Array.isArray(state && state.history) ? state.history : []
    memory = state && state.memory
    if (!memory || typeof memory !== "object") memory = { olives: 0, tests: [], probed: false }
    if (typeof memory.olives !== "number") memory.olives = 0
    if (!Array.isArray(memory.tests)) memory.tests = []

    const [move, mem] = decide(history, memory)
    return [move === "C" ? "C" : "D", mem]
  } catch (e) {
    // never crash: a crash forfeits the whole battle 0:3
    return ["D", memory && typeof memory === "object" ? memory : { olives: 0, tests: [], probed: false }]
  }
}

export default function bot({ history, memory }) {
  const C = "C", D = "D";

  const freshMemory = () => ({
    oppC: 0, oppD: 0,
    recent: [],
    oppDefStreak: 0, oppCoopStreak: 0,
    ourScoreSum: 0,
    everWeDefected: false,
    logp: [0, 0, 0, 0, 0], // AllC, AllD, TFT, Pavlov, Grim
    hardLock: false,
    exploitLock: false,
    suppressRetaliation: 0,
    lastProbe: 0,
  });

  try {
    const n = history.length;

    if (!memory || typeof memory !== "object" || !Array.isArray(memory.logp)) {
      memory = freshMemory();
    }

    if (n === 0) return [C, memory]; // always open with cooperation

    const last = history[n - 1];
    const myLast = last.you === D ? D : C;
    const oppLast = last.opponent === D ? D : C;

    // --- running stats ---
    if (oppLast === C) {
      memory.oppC++; memory.oppCoopStreak++; memory.oppDefStreak = 0;
    } else {
      memory.oppD++; memory.oppDefStreak++; memory.oppCoopStreak = 0;
    }
    memory.recent.push(oppLast);
    if (memory.recent.length > 10) memory.recent.shift();

    const payoff =
      myLast === C && oppLast === C ? 2 :
      myLast === D && oppLast === C ? 3 :
      myLast === C && oppLast === D ? 0 : 1;
    memory.ourScoreSum += payoff;

    // --- Bayesian opponent classification (incremental, O(1)/round) ---
    const eps = 0.05;
    if (n >= 2) {
      const prev = history[n - 2];
      const prevYou = prev.you === D ? D : C;
      const prevOpp = prev.opponent === D ? D : C;

      const predAllC = C;
      const predAllD = D;
      const predTFT = prevYou;
      const predPavlov = prevYou === prevOpp ? prevOpp : (prevOpp === C ? D : C);
      const predGrim = memory.everWeDefected ? D : C;

      const preds = [predAllC, predAllD, predTFT, predPavlov, predGrim];
      for (let i = 0; i < 5; i++) {
        const p = preds[i] === oppLast ? (1 - eps) : eps;
        memory.logp[i] += Math.log(p);
      }
    }
    memory.everWeDefected = memory.everWeDefected || (myLast === D);

    // --- posterior over opponent archetype ---
    const maxLp = Math.max(...memory.logp);
    const exps = memory.logp.map(x => Math.exp(x - maxLp));
    const sumExp = exps.reduce((a, b) => a + b, 0);
    const post = exps.map(x => x / sumExp);
    const [pAllC, pAllD, , , pGrim] = post;
    const pHard = pAllD + pGrim;
    const pMax = Math.max(...post);

    const totalOppMoves = memory.oppC + memory.oppD;
    const oppDefectRate = totalOppMoves ? memory.oppD / totalOppMoves : 0;
    const avgPayoff = memory.ourScoreSum / n;
    const looksRandom = n >= 20 && pMax < 0.4 && oppDefectRate > 0.25 && oppDefectRate < 0.75;

    // 1. Hard-defector backstop (fast trigger on streaks, slower on stats)
    if (
      memory.oppDefStreak >= 3 ||
      (totalOppMoves >= 5 && oppDefectRate > 0.7) ||
      (n >= 4 && pHard > 0.75) ||
      looksRandom
    ) {
      memory.hardLock = true;
    }
    if (memory.hardLock) {
      if (memory.oppCoopStreak >= 3) memory.hardLock = false; // let them redeem
      else return [D, memory];
    }

    // 2. Exploit lock — confirmed non-retaliatory cooperator, harvest 3/round
    if (memory.exploitLock) {
      if (oppLast === D) memory.exploitLock = false; // they finally punched back
      else return [D, memory];
    }
    if (!memory.exploitLock && n >= 8 && pAllC > 0.8 && memory.oppDefStreak === 0 && memory.everWeDefected) {
      memory.exploitLock = true;
      return [D, memory];
    }

    // 3. Payoff safety net — bail if a strategy is clearly losing us value
    if (n >= 20 && avgPayoff < 0.9) {
      memory.hardLock = true;
      return [D, memory];
    }

    // 4. Deliberate probe to classify ambiguous / never-tested opponents
    const dueForProbe =
      oppLast === C && (n === 3 || (pMax < 0.55 && (n - memory.lastProbe) > 12));
    if (dueForProbe) {
      memory.lastProbe = n;
      memory.suppressRetaliation = 1; // pre-forgive their justified response
      return [D, memory];
    }

    // 5. Generous tit-for-tat: retaliate exactly once, then force a resync
    let move;
    if (oppLast === D) {
      if (memory.suppressRetaliation > 0 && pHard < 0.6) {
        memory.suppressRetaliation--;
        move = C;
      } else {
        move = D;
        memory.suppressRetaliation = pHard < 0.6 ? 1 : 0;
      }
    } else {
      move = C;
    }

    return [move, memory];
  } catch (e) {
    // Never forfeit on an exception — mirror opponent, or cooperate if no data.
    const safeMem = {
      oppC: 0, oppD: 0, recent: [], oppDefStreak: 0, oppCoopStreak: 0,
      ourScoreSum: 0, everWeDefected: false, logp: [0, 0, 0, 0, 0],
      hardLock: false, exploitLock: false, suppressRetaliation: 0, lastProbe: 0,
    };
    if (history && history.length > 0) {
      const opp = history[history.length - 1].opponent === "D" ? "D" : "C";
      return [opp, safeMem];
    }
    return ["C", safeMem];
  }
}

export default function bot({ history, memory }) {
  const n = history.length
  const last = history[n - 1]

  if (n === 0) return ["C", null]

  if (memory == null) {
    memory = { mode: "observe" }
  }

  if (memory.mode === "observe") {
    if (n >= 5) {
      const opening = history.slice(0, 5).map(round => round.opponent).join("")

      if (opening === "CDCCC") memory.mode = "exploit"
      else if (opening === "DDDDD") memory.mode = "hard"
      else memory.mode = "friend"
    } else {

      if (last.opponent === "C") return ["C", memory]
      if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
      return ["D", memory]
    }
  }

  if (memory.mode === "exploit" || memory.mode === "hard") {
    return ["D", memory]
  }

  if (n >= 10) {
    const recent = history.slice(-8)
    const defections = recent.reduce(
      (count, round) => count + (round.opponent === "D" ? 1 : 0),
      0,
    )
    if (defections >= 2) {
      memory.mode = "hard"
      return ["D", memory]
    }
  }

  if (last.opponent === "C") return ["C", memory]
  if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
  if (last.you === "D") return ["C", memory]
  return ["D", memory]
}

export default function bottle({history, memory}){
    let n = history.length - 1
    let move
    let C = 0
    let opp
    if (history.length == 0){
        move = "C"
    }
    else{
        opp = history[n].opponent
        if(opp == "C"){
            C += 1
        }

        if(memory > 0&&C > 2){
            move = "C"
            memory = 0
            C = 0
        }
        else if (memory > 0){    
            move = "D"
        }
        else if(opp == "C"){
            move = "C"
        }
        else if (opp == "D"){
           move = "D"
           memory = 1
        }

    }
    return [move, memory]
}

export default function bot({ history, memory }) {
  memory = memory || { streak: 0, punish: false, locked: false };
  if (!history.length) return ["C", memory];

  const last = history.at(-1).opponent;

  memory.streak = last === "D" ? memory.streak + 1 : 0;
  if (memory.streak >= 4) memory.locked = true;

  if (memory.locked) return ["D", memory];

  if (last === "D" && !memory.punish) {
    memory.punish = true;
    return ["D", memory];
  }

  memory.punish = false;
  return ["C", memory];
}

export default function bot({ history, memory }) {
  if (history.length === 0) {
    return ["C", null];
  }
  const lastRound = history[history.length - 1];
  if (lastRound.opponent === "D") {
    const secondLastRound = history.length >= 2 ? history[history.length - 2] : null;
    if (secondLastRound && secondLastRound.opponent === "D") {
      return ["D", memory];
    }
    return ["C", memory];
  }
  return ["C", memory];
}

export default function bot({ history, memory }) {

  if (history.length === 0) {
    return ["C", memory]; 
  }

  const lastOpponentMove = history[history.length - 1].opponent;
  const move = lastOpponentMove;

  return [move, memory];
}

export default function bot({ history, memory }) {
	// If memory is null, set it to an object with a property to track whether the opponent has defected
	memory = memory ?? { opponentDefected: false }

	// Get the opponent's last move
	const lastOpponentMove = history.at(-1)?.opponent
	if (lastOpponentMove === "D")
		memory.opponentDefected = true

	const move = memory.opponentDefected ? "D" : "C"
	return [move, memory]
}

export default function bot({ history, memory }) {
    const round = history.length;
    if (round === 0) return ["C", initMemory()];
    const m = memory ?? initMemory();
    const last = history.at(-1);
    m.everCooperated = m.everCooperated || last.opponent === "C";
    const move = last.opponent === "D"
        ? (Math.random() < 0.12 ? "C" : "D")
        : "C";
    return [move, m];
}

function initMemory() {
    return { everCooperated: false };
}

export default function ({ history, memory }) {
  let m = memory || { bad: 0 };

  if (!history.length) {
    return ["C", m];
  }

  let oppLast = history[history.length - 1].opponent;
  if (oppLast === "D") m.bad++;

  return [m.bad / history.length > 0.25 ? "D" : oppLast, m];
}

export default function bot({ history, memory }) {
    if (history.length === 0) return ["C", { streak: 0 }]

    memory = memory ?? { streak: 0 }
    const lastOpponentMove = history.at(-1).opponent

    if (lastOpponentMove === "D") {
        memory.streak += 1
    } else {
        memory.streak = 0
    }

    // Every 10 rounds while locked in conflict, offer an olive branch
    const round = history.length
    if (memory.streak >= 2 && round % 10 === 0) {
        return ["C", memory]
    }

    const move = memory.streak >= 2 ? "D" : "C"
    return [move, memory]
}

export default function bot({ history, memory }) {
  const n = history.length
  const last = history[n - 1]

  if (n === 0) return ["C", null]

  if (memory == null) {
    memory = { mode: "observe" }
  }

  if (memory.mode === "observe") {
    if (n >= 5) {
      const opening = history.slice(0, 5).map(round => round.opponent).join("")

      if (opening === "CDCCC") memory.mode = "exploit"
      else if (opening === "DDDDD") memory.mode = "hard"
      else memory.mode = "friend"
    } else {

      if (last.opponent === "C") return ["C", memory]
      if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
      return ["D", memory]
    }
  }

  if (memory.mode === "exploit" || memory.mode === "hard") {
    return ["D", memory]
  }

  if (n >= 10) {
    const recent = history.slice(-8)
    const defections = recent.reduce(
      (count, round) => count + (round.opponent === "D" ? 1 : 0),
      0,
    )
    if (defections >= 2) {
      memory.mode = "hard"
      return ["D", memory]
    }
  }

  if (last.opponent === "C") return ["C", memory]
  if (n >= 2 && history[n - 2].you === "D") return ["C", memory]
  if (last.you === "D") return ["C", memory]
  return ["D", memory]
}

export default function bot({history, memory}) {
    const round = history.length;
    if (round === 0) return ["C", initMemory()];
    const m = memory ?? initMemory();
    const last = history.at(-1);
    const lastOpponentMove = last.opponent;
    m.recent.push(lastOpponentMove);
    if (m.recent.length > 3) m.recent.shift();
    const shortDefectRate =
        m.recent.length > 0
            ? m.recent.filter(x => x === "D").length / m.recent.length
            : 0;
    m.coopStreak = lastOpponentMove === "C" ? m.coopStreak + 1 : 0;
    const payoff = payoffOf(last.you, last.opponent);
    m.payoffs.push(payoff);
    if (m.payoffs.length > 6) m.payoffs.shift();
    const avgPayoff = m.payoffs.reduce((a, b) => a + b, 0) / m.payoffs.length;
    if (m.testPending > 0) {
        m.testPending--;
        if (m.testPending === 0) {
            if (lastOpponentMove === "C") {
                m.confirmedSoft = true;
                m.retaliatory = false;
            } else {
                m.confirmedSoft = false;
                m.retaliatory = true;
            }
        }
    }
    const TEST_THRESHOLD = 70;
    const RETEST_THRESHOLD = 20;
    let move;
    if (m.payoffs.length >= 4 && avgPayoff <= 0.8) {
        move = "D";
        m.confirmedSoft = false;
    } else if (m.confirmedSoft) {
        if (lastOpponentMove === "D") {
            m.confirmedSoft = false;
            move = "D";
        } else {
            move = "D";
        }
    } else if (shortDefectRate >= 0.5) {
        move = lastOpponentMove === "D" ? "D" : "C";
    } else if (m.testPending === 0 && m.coopStreak >= (m.retaliatory ? RETEST_THRESHOLD : TEST_THRESHOLD)) {
        move = "D";
        m.testPending = 2;
    } else if (lastOpponentMove === "D") {
        move = Math.random() < 0.4 ? "C" : "D";
    } else {
        move = "C";
    }

	return [move, m] // Move must come 1st, then memory 2nd
}

function payoffOf(you, opp) {
    if (you === "C" && opp === "C") return 2;
    if (you === "D" && opp === "C") return 3;
    if (you === "C" && opp === "D") return 0;
    return 1;
}

function initMemory() {
    return {
        recent: [],
        coopStreak: 0,
        payoffs: [],
        confirmedSoft: false,
        retaliatory: false,
        testPending: 0
    };
}

/**
 * APEX — Adaptive Prisoner's EXpert
 *
 * Strategy architecture (in order of priority):
 *
 * 1. OPPONENT CLASSIFICATION
 *    Continuously classify the opponent into one of several archetypes
 *    based on their behavioural fingerprint in the history so far.
 *
 * 2. ADAPTIVE RESPONSE
 *    Choose a response mode tailored to the detected archetype:
 *    - ALWAYS_DEFECT  → mirror defect (cut losses, earn mutual 1/round)
 *    - ALWAYS_COOPERATE → cooperate almost always; probe once mid-game
 *    - TFT / REACTIVE → cooperate; use Gradual punishment on defections
 *    - RANDOM         → use Tit-for-Two-Tats (forgive single noise)
 *    - GRUDGER        → never provoke; full cooperation
 *    - UNKNOWN        → Gradual (best robust default)
 *
 * 3. GRADUAL PUNISHMENT (core engine)
 *    After the n-th cumulative defection by the opponent, punish with
 *    exactly n consecutive defections, then calm down with 2 cooperations.
 *    This is proportional, memorable, and de-escalating — the strategy
 *    that consistently beats TFT in large-scale tournaments.
 *
 * 4. ENDGAME DEFECTION
 *    In the final ~5 rounds (estimated from round count ≥ 100), defect
 *    against cooperating opponents to squeeze extra points. Risky against
 *    reactive opponents, so only trigger against confirmed cooperators
 *    or once we're deep enough that retaliation cost is minimal.
 *
 * 5. PROBE EXPLOITATION
 *    Against confirmed always-cooperators, defect once around round 30
 *    to test if they retaliate. If they don't, defect regularly (every
 *    ~5 rounds) for free points. If they do, switch to TFT mode.
 */

export default function bot({ history, memory }) {
  // ── Initialise memory ──────────────────────────────────────────────
  memory = memory ?? {
    // Gradual state
    punishRemaining: 0,   // how many more D's to fire in current punishment
    calmRemaining: 0,     // how many more C's in the calming period after punishment
    defectCount: 0,       // total opponent defections seen (= punishment severity counter)

    // Opponent classification
    opponentType: "UNKNOWN", // ALWAYS_DEFECT | ALWAYS_COOPERATE | TFT | RANDOM | GRUDGER | UNKNOWN
    classifiedAt: -1,        // round at which we locked in a classification

    // Exploitation state (for ALWAYS_COOPERATE)
    probedAt: -1,            // round we sent our exploit probe
    exploitMode: false,      // currently exploiting a confirmed pushover

    // Endgame
    endgameStarted: false,
  }

  const round = history.length

  // ── First move: always cooperate ───────────────────────────────────
  if (round === 0) return ["C", memory]

  // ── Update defect count from last opponent move ────────────────────
  const lastOpp = history[round - 1].opponent
  if (lastOpp === "D") memory.defectCount++

  // ── Opponent classification ────────────────────────────────────────
  // Re-classify every 10 rounds until we're confident, then lock in.
  if (round >= 5 && (memory.classifiedAt === -1 || round % 10 === 0) && round <= 80) {
    memory.opponentType = classify(history, round)
    memory.classifiedAt = round
  }

  // ── Endgame logic ─────────────────────────────────────────────────
  // The game runs "at least 100 rounds". We don't know the exact end,
  // so we start being opportunistic from round 95 onward only against
  // opponents who we believe won't retaliate (always-cooperate / grudger
  // already triggered). Against reactive opponents, no endgame defection
  // — the retaliation cost outweighs the gain with unknown rounds left.
  if (round >= 95 && !memory.endgameStarted) {
    if (memory.opponentType === "ALWAYS_COOPERATE" || memory.exploitMode) {
      memory.endgameStarted = true
    }
  }
  if (memory.endgameStarted) {
    return ["D", memory]
  }

  // ── Response by archetype ──────────────────────────────────────────
  const type = memory.opponentType

  // ALWAYS_DEFECT: lock into mutual defection — 1 pt each is better than
  // being exploited for 0 pts while they get 3.
  if (type === "ALWAYS_DEFECT") {
    return ["D", memory]
  }

  // ALWAYS_COOPERATE: mostly cooperate, probe once at round ~30 to confirm,
  // then exploit every few rounds.
  if (type === "ALWAYS_COOPERATE") {
    if (memory.probedAt === -1 && round >= 20) {
      // Send a probe defection
      memory.probedAt = round
      return ["D", memory]
    }
    if (memory.probedAt > 0) {
      const roundsAfterProbe = round - memory.probedAt
      if (roundsAfterProbe >= 2) {
        // Check if they retaliated after our probe
        const theyRetaliated = history
          .slice(memory.probedAt)
          .some(m => m.opponent === "D")
        if (!theyRetaliated) {
          // Confirmed pushover: exploit every 4 rounds
          memory.exploitMode = true
          if (round % 4 === 0) return ["D", memory]
          return ["C", memory]
        } else {
          // They punished — reclassify away from ALWAYS_COOPERATE
          memory.opponentType = "TFT"
          memory.probedAt = -1
        }
      }
    }
    return ["C", memory]
  }

  // RANDOM: use Tit-for-Two-Tats — only defect after two consecutive
  // opponent defections. This avoids noise-triggered escalation spirals.
  if (type === "RANDOM") {
    if (round >= 2) {
      const lastTwo = history.slice(-2)
      if (lastTwo[0].opponent === "D" && lastTwo[1].opponent === "D") {
        return ["D", memory]
      }
    }
    return ["C", memory]
  }

  // GRUDGER: they'll never forgive a single defection, so never defect.
  if (type === "GRUDGER") {
    return ["C", memory]
  }

  // TFT / UNKNOWN / REACTIVE: use Gradual strategy.
  // Gradual cooperates by default; when the opponent has defected n times
  // total, it punishes with n defections then 2 calming cooperations.
  return gradual(lastOpp, memory)
}

// ── Gradual engine ────────────────────────────────────────────────────
function gradual(lastOpp, memory) {
  // Currently in punishment phase
  if (memory.punishRemaining > 0) {
    memory.punishRemaining--
    return ["D", memory]
  }

  // Currently in calming phase
  if (memory.calmRemaining > 0) {
    memory.calmRemaining--
    return ["C", memory]
  }

  // Opponent just defected — start punishment
  if (lastOpp === "D") {
    // Punish with defectCount defections (already incremented above)
    const punishes = memory.defectCount
    if (punishes <= 1) {
      // First defection: punish once, then calm with 2 C's
      memory.punishRemaining = 0   // we fire this round as the 1st punch
      memory.calmRemaining = 2
      return ["D", memory]
    } else {
      // n-th defection: punish n times (first punch now, n-1 deferred)
      memory.punishRemaining = punishes - 1
      memory.calmRemaining = 2
      return ["D", memory]
    }
  }

  // Default: cooperate
  return ["C", memory]
}

// ── Classifier ────────────────────────────────────────────────────────
function classify(history, round) {
  const oppMoves = history.map(m => m.opponent)
  const total = oppMoves.length
  const dCount = oppMoves.filter(m => m === "D").length
  const cCount = total - dCount
  const defectRate = dCount / total

  // Always defect: ≥90% D's
  if (defectRate >= 0.9) return "ALWAYS_DEFECT"

  // Always cooperate: ≥95% C's
  if (defectRate <= 0.05) return "ALWAYS_COOPERATE"

  // Grudger: cooperated solidly until a single defection, then only D's
  // Signature: all C's up to some point, then all D's
  if (dCount >= 3 && cCount >= 3) {
    const firstD = oppMoves.indexOf("D")
    if (firstD >= 3) {
      const afterFirstD = oppMoves.slice(firstD)
      const allDefectAfter = afterFirstD.every(m => m === "D")
      if (allDefectAfter && afterFirstD.length >= 3) return "GRUDGER"
    }
  }

  // TFT / reactive: opponent's move correlates with OUR previous move
  if (round >= 10) {
    let tftMatches = 0
    for (let i = 1; i < history.length; i++) {
      if (history[i].opponent === history[i - 1].you) tftMatches++
    }
    const tftRate = tftMatches / (history.length - 1)
    if (tftRate >= 0.8) return "TFT"
  }

  // Random: high variance, no strong pattern
  if (defectRate > 0.25 && defectRate < 0.75) {
    // Check for alternating or random patterns
    let switches = 0
    for (let i = 1; i < oppMoves.length; i++) {
      if (oppMoves[i] !== oppMoves[i - 1]) switches++
    }
    const switchRate = switches / (oppMoves.length - 1)
    if (switchRate > 0.35) return "RANDOM"
  }

  return "UNKNOWN"
}

export default function bot({ history, memory }) {
  const C = "C", D = "D";

  const init = () => ({
    oppC: 0,
    oppD: 0,
    score: 0,
    mode: "probe",
    punish: 0,
    exploit: 0,
    olive: 0,
    testIdx: 0,
    failedTests: 0,
    lastTestRound: -999,
    everDefected: false,
    hardLock: false,
    cooldown: 0,
    chaos: 0
  });

  try {
    memory = memory && typeof memory === "object" ? memory : init();
    const n = history.length;
    if (n === 0) return [C, memory];

    const last = history[n - 1];
    const myLast = last.you === D ? D : C;
    const oppLast = last.opponent === D ? D : C;

    if (oppLast === C) memory.oppC++;
    else memory.oppD++;

    memory.score +=
      myLast === C && oppLast === C ? 2 :
      myLast === D && oppLast === C ? 3 :
      myLast === C && oppLast === D ? 0 : 1;

    if (myLast === D) memory.everDefected = true;

    if (n >= 2) {
      const p = history[n - 2].opponent === D ? 1 : 0;
      const q = oppLast === D ? 1 : 0;
      if (p !== q) memory.chaos = Math.min(memory.chaos + 1, 100);
      else memory.chaos = Math.max(memory.chaos - 1, 0);
    }

    const total = memory.oppC + memory.oppD;
    const defRate = total ? memory.oppD / total : 0;
    const coopRate = 1 - defRate;
    const avg = memory.score / n;
    const noisy = n >= 18 && memory.chaos >= 10 && defRate > 0.2 && defRate < 0.8;

    if (memory.cooldown > 0) memory.cooldown--;
    if (memory.punish > 0) memory.punish--;

    if (n < 6) {
      const open = [C, C, D, C, C, D];
      return [open[n], memory];
    }

    let dd = 0;
    for (let i = n - 1; i >= 0 && i >= n - 10; i--) {
      if (history[i].you === D && history[i].opponent === D) dd++;
      else break;
    }

    if (
      defRate > 0.72 ||
      (n >= 20 && avg < 0.9) ||
      (noisy && defRate > 0.45)
    ) memory.hardLock = true;

    if (memory.hardLock) {
      if (coopRate > 0.52 && n % 17 === 0) return [C, memory];
      if (coopRate > 0.62 && memory.oppC > memory.oppD + 4) memory.hardLock = false;
      else return [D, memory];
    }

    if (memory.exploit > 0) {
      if (oppLast === D) memory.exploit = 0;
      else return [D, memory];
    }

    if (
      n >= 8 &&
      defRate < 0.05 &&
      memory.everDefected
    ) {
      memory.exploit = 1;
      return [D, memory];
    }

    const testSchedule = [4, 12, 30, 70, 160];
    if (
      memory.failedTests < 2 &&
      memory.testIdx < testSchedule.length &&
      n - memory.lastTestRound > 12 &&
      oppLast === C &&
      defRate < 0.35
    ) {
      const coopStreakNeeded = testSchedule[memory.testIdx];
      let cc = 0;
      for (let i = n - 1; i >= 0; i--) {
        if (history[i].you === C && history[i].opponent === C) cc++;
        else break;
      }
      if (cc >= coopStreakNeeded) {
        memory.lastTestRound = n;
        memory.testIdx++;
        memory.punish = 1;
        return [D, memory];
      }
    }

    if (n >= 2 && history[n - 2].you === D && oppLast === D) {
      memory.failedTests++;
    }

    if (dd >= 4 && memory.cooldown === 0 && defRate < 0.6) {
      memory.cooldown = 7;
      return [C, memory];
    }

    if (oppLast === D) {
      if (memory.punish > 0 && defRate < 0.55) return [C, memory];
      if (defRate > 0.55) return [D, memory];
      if (n % 3 === 0 && defRate < 0.35) return [C, memory];
      return [D, memory];
    }

    if (n >= 96) {
      if (defRate < 0.08) return [D, memory];
      if (defRate > 0.5) return [D, memory];
    }

    return [C, memory];
  } catch {
    const safe = {
      oppC: 0, oppD: 0, score: 0, mode: "probe", punish: 0, exploit: 0,
      olive: 0, testIdx: 0, failedTests: 0, lastTestRound: -999,
      everDefected: false, hardLock: true, cooldown: 0, chaos: 0
    };
    if (history && history.length) {
      const opp = history[history.length - 1].opponent === "D" ? "D" : "C";
      return [opp, safe];
    }
    return [D, safe];
  }
}

