         * Forgive isolated D.
         *
         * This is crucial for noisy / forgiving opponents.
         */
        if (previousOpp === C) {
            return [C, memory];
        }

        /*
         * Second consecutive D:
         * punish once.
         */
        return [D, memory];
    }

    // ================================================================
    // DEFAULT COOPERATION
    // ================================================================

    return [C, memory];
}

